CREATE POLICY items_traffic_classify ON public.demand_items FOR UPDATE TO authenticated USING(public.has_role(auth.uid(),'traffic') AND status='Aprovado') WITH CHECK(public.has_role(auth.uid(),'traffic') AND status='Aprovado');
CREATE OR REPLACE FUNCTION public.validate_item_update() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN IF public.has_role(auth.uid(),'traffic') AND old.status='Aprovado' AND (to_jsonb(new)-'performance_status')=(to_jsonb(old)-'performance_status') THEN RETURN new; END IF; IF NOT public.has_role(auth.uid(),'editor') OR old.assigned_to IS DISTINCT FROM auth.uid() THEN RAISE EXCEPTION 'Apenas o editor responsável pode alterar o andamento'; END IF; IF (to_jsonb(new)-'status') IS DISTINCT FROM (to_jsonb(old)-'status') THEN RAISE EXCEPTION 'Você só pode alterar o andamento de seus itens'; END IF; IF new.status NOT IN ('Em edição','Aguardando aprovação') THEN RAISE EXCEPTION 'Status não permitido para editor'; END IF; END IF; IF new.status='Aguardando aprovação' AND NOT EXISTS(SELECT 1 FROM public.creative_versions WHERE item_id=new.id) THEN RAISE EXCEPTION 'Anexe um arquivo final antes de enviar para aprovação'; END IF; IF new.status='Aprovado' AND NOT EXISTS(SELECT 1 FROM public.creative_versions v JOIN public.creative_reviews r ON r.version_id=v.id WHERE v.item_id=new.id AND r.decision='Aprovado' AND NOT EXISTS(SELECT 1 FROM public.creative_reviews newer WHERE newer.version_id=r.version_id AND (newer.created_at,newer.id)>(r.created_at,r.id))) THEN RAISE EXCEPTION 'Aprove uma versão do arquivo final'; END IF; RETURN new; END $$;
CREATE OR REPLACE FUNCTION public.validate_publication_version() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE latest_verdict text; BEGIN IF NOT (public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'traffic')) THEN RAISE EXCEPTION 'Sem permissão para publicar'; END IF; PERFORM 1 FROM public.creative_versions WHERE id=new.version_id FOR UPDATE; SELECT decision INTO latest_verdict FROM public.creative_reviews WHERE version_id=new.version_id ORDER BY created_at DESC,id DESC LIMIT 1; IF latest_verdict IS DISTINCT FROM 'Aprovado' THEN RAISE EXCEPTION 'A versão selecionada não está aprovada'; END IF; RETURN new; END $$;
CREATE TRIGGER validate_publication_version BEFORE INSERT OR UPDATE ON public.publications FOR EACH ROW EXECUTE FUNCTION public.validate_publication_version();
CREATE OR REPLACE FUNCTION public.review_creative(target_version uuid, verdict text, observation text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE target_item uuid; BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Apenas administradores podem revisar'; END IF; IF verdict NOT IN ('Aprovado','Ajustes solicitados') THEN RAISE EXCEPTION 'Decisão inválida'; END IF; IF verdict='Ajustes solicitados' AND length(trim(observation))=0 THEN RAISE EXCEPTION 'Informe os ajustes necessários'; END IF; SELECT v.item_id INTO target_item FROM public.creative_versions v JOIN public.files f ON f.id=v.file_id JOIN storage.objects o ON o.name=f.path AND o.bucket_id='dr-files' WHERE v.id=target_version AND f.purpose='final' FOR UPDATE OF v; IF target_item IS NULL THEN RAISE EXCEPTION 'Arquivo final não encontrado'; END IF; PERFORM 1 FROM public.demand_items WHERE id=target_item FOR UPDATE; INSERT INTO public.creative_reviews(version_id,decision,notes) VALUES(target_version,verdict,observation); UPDATE public.demand_items SET status=verdict WHERE id=target_item; END $$;
CREATE OR REPLACE FUNCTION public.validate_financial_item() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF new.item_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.demand_items i JOIN public.demands d ON d.id=i.demand_id WHERE i.id=new.item_id AND d.offer_id=new.offer_id) THEN RAISE EXCEPTION 'Criativo não pertence à oferta'; END IF; RETURN new; END $$;
CREATE TRIGGER validate_financial_item BEFORE INSERT OR UPDATE ON public.performance_daily FOR EACH ROW EXECUTE FUNCTION public.validate_financial_item();